def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    if n >= 99:
        return 'D'

    if opp_d == 0:
        if n >= 95:
            return 'D'
        if n >= 80:
            return 'D' if rng.random() < 0.8 else 'C'
        if n >= 50:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'D' if rng.random() < 0.4 else 'C'

    if opp_c == 0:
        if n >= 6:
            return 'D'
        if n >= 2 and me[-1] == 'C' and me[-2] == 'C':
            return 'D'
        return 'C'

    if n >= 10:
        coop_rate = opp_c / n
        recent_opp = opp[-5:]
        recent_c = sum(1 for a in recent_opp if a == 'C')
        if 0.35 <= coop_rate <= 0.65 and recent_c <= 3:
            return 'D'

    dd_run = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            dd_run += 1
        else:
            break

    if dd_run >= 3:
        return 'C'
    if dd_run == 2 and rng.random() < 0.6:
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_c > opp_d or (n > 10 and opp_c > n * 0.4):
                return 'C'
            return 'D'
        else:
            if opp_c > opp_d:
                return 'C'
            if last_me == 'C' and opp_c > 0:
                return 'C'
            return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            forgiven = 0
            retaliated = 0
            for i in range(n - 1):
                if me[i] == 'D':
                    if opp[i + 1] == 'C':
                        forgiven += 1
                    else:
                        retaliated += 1
            if forgiven > retaliated or opp_d <= max(1, n // 10):
                if n >= 90:
                    return 'D'
                if n >= 60:
                    return 'D' if rng.random() < 0.7 else 'C'
                return 'D' if rng.random() < 0.4 else 'C'
            else:
                return 'C'
        else:
            if opp_d <= max(1, n // 20):
                if n >= 95:
                    return 'D'
                if n >= 80:
                    return 'D' if rng.random() < 0.5 else 'C'
                if n >= 40:
                    return 'D' if rng.random() < 0.2 else 'C'
            return 'C'
